#!/usr/bin/env bash

set -e -x

# Build most docs, except those which depend on sources generated by the build process.

SCRIPT_LOCATION=$(dirname $0)
SCRIPT_LOCATION=$(realpath $SCRIPT_LOCATION)


if [[ $# -ne 1 ]]; then
  echo Usage: $(basename $0) "<plugin-dir>"
  exit 1
fi

PLUGIN_DIR=$1

pushd ${SCRIPT_LOCATION}
GIT_ROOT=`git rev-parse --show-toplevel`
popd

GUIDES="$(find $GIT_ROOT/plugins/$PLUGIN_DIR/docs/plugin-guides/* -maxdepth 0)"
echo $GUIDES

